/**
 * Prescription checks, set A: interactions, combination brands and doses.
 * Prescriptions are teaching examples written in the Indian style
 * (Tab, dose, morning-noon-night). Doses are for learning only.
 */
import { R, type Review } from "./review-kit";

export const REVIEWS_A: Review[] = [
  R("rv-nexplus", "Mrs Shah, 42, Surat", "Anxious and low. She has been taking clonazepam 0.5 mg at night from her family doctor for a year.", ["Tab Nexito Plus (escitalopram 10 mg + clonazepam 0.5 mg)  0-0-1", "Tab Lonazep 0.5 mg  0-0-1", "Review after 30 days"], "Clonazepam is given twice: Nexito Plus already has it", ["Escitalopram 10 mg is above the usual maximum", "Escitalopram must always be taken in the morning", "Clonazepam must never be combined with an SSRI"], "Nexito Plus is escitalopram with clonazepam in one tablet. Adding Lonazep, which is clonazepam, doubles the benzodiazepine dose, with more sedation, falls and dependence. Always read what is inside a combination brand.", "Escitalopram 10 mg is a normal dose; the maximum is 20 mg. It can be taken morning or night. A short course of a benzodiazepine alongside an SSRI is sometimes used, so the combination is not forbidden; the problem is the duplicate.", ["escitalopram", "clonazepam"], "anxiety", 2, "combination brand duplicate", "Read the contents of a combination brand before adding another medicine."),
  R("rv-trinicalm", "Mr Rawat, 70, Dehradun", "Long-standing schizophrenia. He has become forgetful and constipated, and his family say he is muddled at night.", ["Tab Trinicalm Plus (trifluoperazine 5 mg + trihexyphenidyl 2 mg)  1-0-1", "Tab Pacitane 2 mg  1-0-1"], "Trihexyphenidyl is given twice in a confused man", ["Trifluoperazine is never used for schizophrenia", "Trinicalm Plus must be taken only at night", "His doses are far too low to work"], "Trinicalm Plus already contains trihexyphenidyl. Pacitane is the same medicine, so he takes 8 mg a day of an anticholinergic. In older people that worsens memory, constipation and night confusion. The anticholinergic should be reviewed and probably reduced or stopped.", "Trifluoperazine is a first-generation antipsychotic used in schizophrenia. Twice-daily dosing is normal. The doses are ordinary, not too low; the problem is the duplicated anticholinergic.", ["trihexyphenidyl", "trifluoperazine"], "antipsychotics", 3, "duplicate anticholinergic", "Spot a duplicated anticholinergic in an older adult."),
  R("rv-libotryp", "Mrs Kaur, 81, Patiala", "Frail, lives alone, has fallen twice. Prescribed for 'nerves and sleep'.", ["Cap Libotryp (chlordiazepoxide 5 mg + amitriptyline 12.5 mg)  0-0-2"], "Two falls-risk medicines in one frail woman", ["Amitriptyline is not available in India", "The dose should be taken in the morning to work", "Chlordiazepoxide is only used in children"], "Libotryp combines a long-acting benzodiazepine with an anticholinergic tricyclic. In a frail older woman who already falls, both add sedation, unsteadiness and confusion. A safer plan treats the anxiety or depression properly, without these.", "Amitriptyline is widely sold in India. Night dosing fits a sedating medicine; morning dosing would not make it safer. Chlordiazepoxide is used in adults, notably for alcohol withdrawal.", ["chlordiazepoxide", "amitriptyline"], "anxiety", 3, "older adult falls risk", "Recognise high-risk combination brands in frail older people."),
  R("rv-oleanzplus", "Mr Jain, 38, Indore", "Bipolar depression. He has a family history of diabetes and a waist of 102 cm.", ["Tab Oleanz Plus (olanzapine 5 mg + fluoxetine 20 mg)  0-0-1", "No blood tests planned"], "No weight, sugar or lipid checks are planned", ["Fluoxetine cannot be combined with any antipsychotic", "Olanzapine plus fluoxetine is never used in bipolar depression", "Fluoxetine 20 mg is a dangerous dose"], "Olanzapine causes weight gain and raises sugar and lipids. With a large waist and a family history of diabetes, baseline weight, waist, fasting sugar or HbA1c and lipids, then regular repeats, are essential.", "Olanzapine with fluoxetine is an established treatment for bipolar depression. Fluoxetine 20 mg is the usual dose. Some antipsychotic and SSRI combinations need care for interactions, but they are not banned.", ["olanzapine", "fluoxetine"], "antipsychotics", 3, "missing metabolic monitoring", "Plan metabolic checks for olanzapine."),
  R("rv-petrilbeta", "Ms Rao, 24, Hyderabad", "Panic disorder and childhood asthma; she still uses a blue inhaler some months.", ["Tab Petril Beta (clonazepam 0.5 mg + propranolol 10 mg)  1-0-1"], "Its propranolol can set off her asthma", ["Clonazepam does not help panic", "Propranolol 10 mg is above the maximum dose", "Twice-daily dosing is impossible with this brand"], "Petril Beta contains propranolol, a beta-blocker that also blocks the airway's beta-2 receptors. In asthma it can cause bronchospasm and stop salbutamol working. It should not be used.", "Clonazepam can reduce panic, though it is not first-line long term. Propranolol 10 mg is a small dose. Twice daily is a normal schedule.", ["propranolol", "clonazepam"], "anxiety", 3, "asthma and beta-blocker", "Spot propranolol hidden in a combination brand in asthma."),
  R("rv-ultracet", "Mr Mehta, 55, Mumbai", "Depression on sertraline 150 mg. Now has knee pain after a fall.", ["Tab Daxid 50 mg  1-0-2 (continue)", "Tab Ultracet (tramadol 37.5 mg + paracetamol 325 mg)  1-1-1"], "Ultracet hides tramadol: serotonin risk", ["Paracetamol is dangerous with sertraline", "Daxid is not a brand of sertraline", "Sertraline 150 mg is above the maximum"], "Ultracet is tramadol with paracetamol. Tramadol raises serotonin, so with high-dose sertraline serotonin syndrome is a risk, and tramadol also lowers the seizure threshold. Plain paracetamol is a safer start.", "Paracetamol on its own is the safer painkiller with an SSRI. Daxid is a sertraline brand. The maximum sertraline dose is 200 mg, so 150 mg is allowed.", ["sertraline"], "antidepressants", 2, "hidden tramadol", "Recognise tramadol inside a common pain brand."),
  R("rv-li-nsaid", "Mr Thomas, 45, Kochi", "Stable on lithium for six years, last level 0.7. Severe back pain after lifting.", ["Tab Licab 300 mg  1-0-2 (continue)", "Tab Zerodol (aceclofenac 100 mg)  1-0-1 for 10 days"], "Aceclofenac pushes lithium levels up", ["Lithium must be taken only in the morning", "A lithium level of 0.7 is toxic", "Licab is not a lithium brand"], "Aceclofenac is an anti-inflammatory painkiller. Like ibuprofen and diclofenac it reduces kidney clearance of lithium, so levels can climb into toxicity. Paracetamol is preferred; if an anti-inflammatory is essential, an early level check is needed.", "Lithium is often given at night or split; there is no morning-only rule. 0.7 is within the usual range. Licab is a lithium carbonate brand.", ["lithium"], "stabilisers", 2, "lithium interaction", "Spot an anti-inflammatory that raises lithium."),
  R("rv-li-ace", "Mrs Sen, 58, Kolkata", "On lithium, last level 0.6. New high blood pressure found today.", ["Tab Lithosun SR 400 mg  0-0-1 (continue)", "Tab Envas (enalapril 5 mg)  1-0-0", "Next lithium level: routine, in six months"], "Enalapril needs an early lithium level", ["Enalapril must never be used in anyone with bipolar disorder", "Slow-release lithium cannot be taken at night", "Her lithium level is too high and must be halved"], "ACE inhibitors such as enalapril reduce lithium clearance. A lithium level and kidney function check soon after starting, and after any dose change, are needed. Leaving it six months risks toxicity.", "Enalapril can be used with care; there is no blanket ban in bipolar disorder. Slow-release lithium is commonly taken at night. A level of 0.6 is within range.", ["lithium"], "stabilisers", 3, "lithium monitoring after a new medicine", "Plan an early lithium level when a kidney-affecting medicine starts."),
  R("rv-clz-cipro", "Mr Prakash, 33, Coimbatore", "On clozapine 400 mg, level last month in range. Urine infection today.", ["Tab Sizopin 100 mg  1-0-3 (continue)", "Tab Ciplox (ciprofloxacin 500 mg)  1-0-1 for 5 days"], "Ciprofloxacin will push clozapine up", ["Clozapine 400 mg is above the maximum", "Ciprofloxacin lowers white cells with clozapine more than any antibiotic", "Clozapine must be split into equal doses"], "Ciprofloxacin blocks CYP1A2, clozapine's main enzyme. Levels can rise with sedation, drooling and fits. Another antibiotic, or a lower clozapine dose with level checks, is safer.", "The maximum clozapine dose is 900 mg. The main danger from ciprofloxacin is the raised level, not the white cell count. Clozapine is often given with a larger night dose for sedation.", ["clozapine"], "antipsychotics", 3, "clozapine interaction", "Spot an antibiotic that raises clozapine."),
  R("rv-clz-bloods", "Mr Hegde, 29, Udupi", "Treatment-resistant schizophrenia. Clozapine is started in clinic today.", ["Tab Lozapin 25 mg  0-0-½, increase by 25 mg every two to three days", "Blood count: not planned", "Bowel advice: not given"], "No blood count monitoring is planned", ["Clozapine should start at 200 mg", "Clozapine is only given as an injection", "Clozapine must never be increased slowly"], "Clozapine can wipe out white cells (agranulocytosis), most often early on. A baseline and then regular blood counts are mandatory. Bowel advice is also missing: constipation can be dangerous.", "Clozapine starts at 12.5 mg and rises slowly because of low blood pressure and fits. It is a tablet, not an injection. Slow increases are the rule, not a mistake.", ["clozapine"], "antipsychotics", 2, "clozapine monitoring", "Recall mandatory blood counts on clozapine."),
  R("rv-vpa-woman", "Ms Ansari, 23, Lucknow", "First manic episode. Single, says she may marry next year. No contraception.", ["Tab Valparin Chrono 500 mg  0-0-1, increase to 1-0-1", "No pregnancy discussion recorded"], "Valproate with no pregnancy prevention plan", ["Valproate does not work in mania", "Valparin is not a valproate brand", "500 mg is far above the usual dose"], "Valproate carries a high risk of birth defects and later learning problems in children exposed in the womb. In women who could become pregnant it is avoided unless nothing else works, and only with a clear pregnancy prevention plan and informed consent.", "Valproate does treat mania. Valparin is a valproate brand. 500 mg is a common starting dose.", ["valproate"], "stabilisers", 2, "valproate and pregnancy", "Recall the valproate pregnancy rule."),
  R("rv-cbz-hla", "Mr Nguyen, 35, a Vietnamese engineer in Pune", "Bipolar disorder. Carbamazepine is chosen after weight gain on other medicines.", ["Tab Mazetol 200 mg  0-0-1, increase to 1-0-1", "HLA-B*1502 test: not done"], "HLA-B*1502 must be tested first", ["Carbamazepine always causes weight gain", "Carbamazepine is only for children", "200 mg is a dangerous starting dose"], "The HLA-B*1502 gene, common in many Southeast Asian groups, sharply raises the risk of Stevens-Johnson syndrome with carbamazepine. Testing first, and avoiding carbamazepine if positive, is the rule.", "Carbamazepine is relatively weight-neutral. It is used in adults. 200 mg is a usual start.", ["carbamazepine"], "stabilisers", 4, "HLA testing", "Recall HLA-B*1502 testing before carbamazepine."),
  R("rv-ltg-vpa", "Mrs Iqbal, 36, Bhopal", "Bipolar depression on valproate 1000 mg. Lamotrigine is added.", ["Tab Valparin 500 mg  1-0-1 (continue)", "Tab Lamitor 50 mg  1-0-0 from today"], "Lamotrigine starts too high beside valproate", ["Lamotrigine cannot treat bipolar depression", "Valproate must be stopped before any lamotrigine", "Lamotrigine must be taken three times a day"], "Valproate roughly doubles lamotrigine levels. A fast start raises the risk of serious rash, including Stevens-Johnson syndrome. With valproate, lamotrigine starts at about half the usual starting dose and rises slowly.", "Lamotrigine is used to prevent bipolar depression. The two can be combined with care. Once or twice daily dosing is usual.", ["lamotrigine", "valproate"], "stabilisers", 4, "lamotrigine titration", "Adjust lamotrigine titration beside valproate."),
  R("rv-esc-elderly", "Mr Rao, 84, Visakhapatnam", "Depression after his wife's death. On amlodipine and a water tablet.", ["Tab Nexito 20 mg  1-0-0", "Tab Aquazide (hydrochlorothiazide 12.5 mg)  1-0-0 (continue)"], "Above the usual escitalopram cap after 65", ["Escitalopram cannot be used in depression after bereavement", "Hydrochlorothiazide raises escitalopram levels", "Escitalopram must be taken at night"], "Because of QT risk, escitalopram is usually capped at 10 mg after 65. With a thiazide, low sodium is also a risk, so sodium should be checked early.", "Depression after bereavement can be treated when it meets criteria. Hydrochlorothiazide does not raise escitalopram levels; it adds a sodium risk. Morning or night dosing are both fine.", ["escitalopram"], "antidepressants", 3, "dose for age", "Adjust escitalopram dose for older adults."),
  R("rv-fluox-child", "Arnav, 15, Delhi", "Moderate depression after a full assessment. Therapy has started.", ["Cap Fludac 20 mg  1-0-0", "Follow-up: in three months"], "No early review for suicidal thoughts", ["Fluoxetine is never used under 18", "20 mg is too low to help anyone", "Fluoxetine must be taken at night"], "Under 25s can have more suicidal thinking early in antidepressant treatment. Close early follow-up, with the family aware of warning signs, is needed, not a three-month gap.", "Fluoxetine is the best-supported antidepressant in adolescents. 20 mg is a common dose (often after a lower start). Morning dosing is usual because it can be activating.", ["fluoxetine"], "antidepressants", 3, "missing early review", "Plan early review when a young person starts an antidepressant."),
  R("rv-two-ssri", "Ms Pillai, 30, Chennai", "Changed doctors twice. Brought all her strips to clinic.", ["Tab Serta 100 mg  1-0-0 (from Dr A)", "Tab Stalopam 10 mg  0-0-1 (from Dr B)"], "Two SSRIs are being taken at once", ["Sertraline 100 mg is above the maximum", "Escitalopram cannot be taken at night", "Neither medicine treats depression"], "Serta is sertraline and Stalopam is escitalopram, both SSRIs. Taking two raises the risk of serotonin syndrome and side effects with no proven gain. One should be chosen and the other tapered.", "The sertraline maximum is 200 mg. Escitalopram can be taken at night. Both are standard antidepressants.", ["sertraline", "escitalopram"], "antidepressants", 2, "duplicate class", "Spot two medicines of the same class from different prescribers."),
  R("rv-bup-preg", "Mrs Kulkarni, 29, Nagpur", "Three months pregnant, opioid dependent on heroin, now on buprenorphine.", ["Tab Addnok 8 mg  1-0-0 sublingual", "Advice: stop buprenorphine as soon as possible because of the pregnancy"], "Stopping buprenorphine in pregnancy is riskier", ["Buprenorphine must be swallowed whole", "8 mg is too high for anyone", "Buprenorphine is only used for alcohol"], "In pregnancy, continuing opioid substitution (buprenorphine or methadone) is safer for mother and baby than stopping, which risks withdrawal, relapse and overdose. The newborn may need monitoring for withdrawal.", "Buprenorphine is taken under the tongue. 8 mg is a common maintenance dose. It treats opioid, not alcohol, dependence.", ["buprenorphine"], "substance", 4, "opioid treatment in pregnancy", "Keep opioid substitution going in pregnancy."),
  R("rv-dis-noconsent", "Mr Reddy, 50, Warangal", "Alcohol dependence. His wife asks for 'a medicine to put in his tea so he stops'.", ["Tab Esperal 250 mg  1-0-0, to be mixed into tea by wife"], "Disulfiram given without his consent", ["250 mg is too low to work", "Disulfiram must be injected", "Disulfiram is only for opioid dependence"], "Hidden disulfiram is unethical and dangerous: if he drinks without knowing, the reaction can be severe. Disulfiram only works with informed consent, ideally with supervised dosing he agrees to.", "250 mg is a usual dose. It is a tablet. It is used for alcohol, not opioids.", ["disulfiram"], "substance", 2, "consent", "Recall that disulfiram needs informed consent."),
  R("rv-nal-heroin", "Mr Singh, 26, Amritsar", "Uses heroin daily, last use this morning. Wants to stop.", ["Tab Naltima 50 mg  1-0-0 from today"], "Naltrexone now will trigger withdrawal", ["50 mg is above the usual dose", "Naltrexone is only for alcohol", "Naltrexone must be taken at night"], "Naltrexone blocks opioid receptors. Given while heroin is in the body, it causes severe withdrawal. It starts only after an opioid-free gap and a negative test, or another treatment such as buprenorphine is used.", "50 mg is the usual dose. Naltrexone is used for both alcohol and opioid relapse prevention. Timing of day does not matter.", ["naltrexone"], "substance", 3, "precipitated withdrawal", "Recall the opioid-free gap before naltrexone."),
  R("rv-bpn-timing", "Mr Lalchhanhima, 31, Aizawl", "Uses heroin; last injected two hours ago. No withdrawal signs yet.", ["Tab Addnok 8 mg  sublingual, first dose now in clinic"], "Too early: wait for clear withdrawal", ["Buprenorphine must be swallowed", "Buprenorphine is unsafe in anyone who has injected", "8 mg is the maximum daily dose"], "Buprenorphine pushes heroin off receptors and gives only a partial signal. Given too soon, it causes precipitated withdrawal. The first dose waits until withdrawal is clear on a scale, often starting lower.", "It is taken under the tongue. It is a standard treatment for people who inject. Daily doses can go well above 8 mg.", ["buprenorphine"], "substance", 4, "buprenorphine induction", "Time the first buprenorphine dose safely."),
  R("rv-benzo-ever", "Mrs Agarwal, 79, Kolkata", "On alprazolam 0.5 mg at night for twelve years. Two falls this year.", ["Tab Alprax 0.5 mg  0-0-1, continue", "Repeat for 6 months"], "Needs a review and a slow taper plan", ["Alprazolam 0.5 mg is above the maximum", "Alprazolam must be stopped today", "Alprazolam should be switched to an injection"], "Long-term benzodiazepines in older people cause falls, fractures and confusion. The kind plan is a discussion and a slow, supported taper. Stopping suddenly after years risks withdrawal and fits.", "0.5 mg is a low dose. Stopping abruptly is dangerous. There is no reason for an injection.", ["alprazolam"], "anxiety", 3, "long-term benzodiazepines", "Plan a slow taper for long-term benzodiazepines in older adults."),
  R("rv-zol-old", "Mr Iyer, 86, Chennai", "Cannot sleep. Lives with his son; gets up at night to pass urine.", ["Tab Zolfresh 10 mg  0-0-1"], "Zolpidem 10 mg is too much at 86", ["Zolpidem is not a sleeping tablet", "Zolpidem must be taken in the morning", "Zolpidem has no risk of falls"], "Older adults clear zolpidem more slowly. A lower dose (5 mg) is used if at all, and night-time toilet trips make falls likely. Sleep habits and causes such as the bladder come first.", "Zolpidem is a sleeping tablet. It is taken at bedtime. It does raise falls risk.", ["zolpidem"], "anxiety", 2, "dose for age", "Lower hypnotic doses in older adults."),
  R("rv-mph-noht", "Aarav, 9, Bengaluru", "ADHD diagnosed after school and home reports. Starting medicine.", ["Tab Inspiral 5 mg  1-1-0", "Height, weight, pulse, blood pressure: not recorded"], "No baseline growth, pulse or blood pressure", ["Methylphenidate is never used in children", "The dose must be taken at bedtime", "5 mg is above the maximum"], "Stimulants can slow growth, curb appetite and raise pulse and blood pressure. A baseline is needed, then regular checks on a growth chart.", "Methylphenidate is first-line in school-age ADHD. Bedtime dosing would ruin sleep. 5 mg is a low starting dose.", ["methylphenidate"], "child", 2, "stimulant baseline checks", "Record baseline growth and cardiovascular checks before stimulants."),
  R("rv-atx-par", "Riya, 14, Pune", "ADHD and anxiety. On paroxetine 20 mg.", ["Tab Pexep 20 mg  1-0-0 (continue)", "Cap Attentin 40 mg  1-0-0, full target dose from day one"], "Paroxetine will push atomoxetine up", ["Atomoxetine is a stimulant", "Paroxetine is not used for anxiety", "Atomoxetine must be given at night only"], "Atomoxetine is cleared by CYP2D6, which paroxetine strongly blocks. Levels can rise many-fold. Start low and increase slowly, watching pulse and blood pressure.", "Atomoxetine is a non-stimulant. Paroxetine is used for anxiety disorders. Atomoxetine can be given morning or split.", ["atomoxetine", "paroxetine"], "child", 4, "CYP2D6 interaction", "Adjust atomoxetine beside a CYP2D6 blocker."),
  R("rv-don-pulse", "Mrs Okafor, 79, London", "Alzheimer's disease. Pulse 52 at rest. On bisoprolol for her heart.", ["Tab Donecept 5 mg  0-0-1"], "Her slow pulse needs checking first", ["Donepezil is only for vascular dementia", "5 mg is above the maximum", "Donepezil must be taken in the morning only"], "Donepezil slows the heart. With a resting pulse of 52 and a beta-blocker, the risk of fainting is real. An ECG and specialist view come first.", "Donepezil is used in Alzheimer's disease. 5 mg is the usual start. Night or morning dosing are both used; vivid dreams can make morning better.", ["donepezil"], "neurocognitive", 3, "pulse check", "Check pulse before donepezil."),
  R("rv-mem-ckd", "Mr Sharma, 80, Haridwar", "Moderate Alzheimer's disease and severe kidney disease.", ["Tab Admenta 10 mg  1-0-1"], "Too high for severe kidney disease", ["Memantine cannot be used with donepezil", "Memantine is only for mild dementia", "Memantine must be crushed"], "Memantine is cleared by the kidneys. In severe kidney impairment its dose is reduced (often to 10 mg a day).", "Memantine is often combined with donepezil. It is for moderate to severe Alzheimer's disease. It is swallowed as a tablet.", ["memantine"], "neurocognitive", 4, "dose for kidney function", "Adjust memantine for kidney function."),
  R("rv-amis-ckd", "Mrs Das, 67, Cuttack", "Psychosis. Creatinine clearance markedly reduced.", ["Tab Amipride 200 mg  1-0-1"], "Too high for her kidney function", ["Amisulpride is not an antipsychotic", "Amisulpride raises blood sugar more than any other drug", "Amisulpride must be given as a depot"], "Amisulpride leaves the body almost unchanged in urine. With poor kidney function it builds up, so the dose is reduced or another antipsychotic chosen.", "Amisulpride is an antipsychotic. It is relatively light on blood sugar. It is a tablet.", ["amisulpride"], "antipsychotics", 4, "dose for kidney function", "Adjust amisulpride for kidney function."),
  R("rv-pgb-ckd", "Mr Reddy, 66, Nellore", "On dialysis. Burning feet from diabetes.", ["Cap Pregeb 150 mg  1-0-1"], "Far too high a dose on dialysis", ["Pregabalin is only for epilepsy", "Pregabalin must be taken once a month", "Pregabalin is safe at any dose in kidney failure"], "Pregabalin is cleared entirely by the kidneys. On dialysis it is given at a much lower dose, often with a supplement after dialysis. Too much causes drowsiness and confusion.", "Pregabalin is used for nerve pain and anxiety. Daily dosing is normal. It is not safe at usual doses in kidney failure.", ["pregabalin"], "anxiety", 4, "dose for kidney function", "Adjust pregabalin for kidney failure."),
  R("rv-li-preg", "Mrs Menon, 31, Thrissur", "Bipolar disorder, stable on lithium for years. Now six months pregnant.", ["Tab Licab 400 mg  0-0-1 (continue)", "Lithium level: next at delivery"], "Lithium levels need frequent checks now", ["Lithium is safe at any level in pregnancy", "Lithium must be stopped the moment pregnancy is known", "Lithium has no effect on the baby"], "Kidney clearance rises in pregnancy, so lithium levels fall, then rise sharply after delivery. Levels are checked often, the dose adjusted, and a delivery plan made with the obstetric team.", "Lithium is never safe at any level. Stopping suddenly risks relapse; decisions are made together. Lithium can affect the baby's heart and thyroid, so specialist scans and care are needed.", ["lithium"], "stabilisers", 5, "lithium in pregnancy", "Plan lithium monitoring in pregnancy."),
  R("rv-pal-ckd", "Mr Khan, 52, Aligarh", "Schizophrenia. Severe kidney impairment on recent tests.", ["Inj Invega Sustenna 150 mg day 1, then 100 mg day 8, then monthly"], "Avoided in severe kidney impairment", ["Paliperidone is only given by mouth", "Paliperidone is a mood stabiliser", "The loading doses must be given on the same day"], "Unlike risperidone, paliperidone leaves mainly through the kidneys. The long-acting injection is not used in severe kidney impairment, and doses are lowered in milder impairment.", "Paliperidone comes as tablets and injections. It is an antipsychotic. The two loading injections are given about seven days apart.", ["paliperidone"], "antipsychotics", 5, "depot and kidneys", "Check kidney function before paliperidone injections."),
  R("rv-que-clar", "Ms Bose, 41, Durgapur", "Bipolar disorder on quetiapine 600 mg. Chest infection.", ["Tab Qutipin 300 mg  1-0-1 (continue)", "Tab Claribid (clarithromycin 500 mg)  1-0-1"], "Clarithromycin will push quetiapine up", ["Quetiapine cannot treat bipolar disorder", "Clarithromycin lowers quetiapine levels", "Quetiapine 600 mg is above the maximum"], "Quetiapine is cleared by CYP3A4. Clarithromycin is a strong CYP3A4 blocker, so quetiapine builds up, with sedation and low blood pressure. Another antibiotic avoids it.", "Quetiapine treats bipolar disorder. Clarithromycin raises, not lowers, quetiapine. The maximum is 800 mg.", ["quetiapine"], "antipsychotics", 3, "CYP3A4 interaction", "Spot clarithromycin as a strong enzyme blocker."),
  R("rv-lur-cbz", "Mr Pandit, 39, Jammu", "Bipolar disorder on carbamazepine. Depressed now.", ["Tab Zen Retard 400 mg  1-0-1 (continue)", "Tab Lurasid 40 mg  0-0-1 with food"], "Carbamazepine wipes out lurasidone", ["Lurasidone must be taken on an empty stomach", "Lurasidone is only for children", "40 mg is above the maximum"], "Carbamazepine strongly speeds up CYP3A4. Lurasidone levels fall to almost nothing, so the combination is not allowed. Another option is chosen.", "Lurasidone should be taken with food. It is licensed for adults (and some adolescent uses). 40 mg is a usual dose.", ["lurasidone", "carbamazepine"], "antipsychotics", 4, "enzyme inducer", "Avoid lurasidone with carbamazepine."),
  R("rv-cbz-pill", "Ms Fernandes, 26, Panaji", "Bipolar disorder. Uses the combined pill for contraception.", ["Tab Tegretol CR 200 mg  1-0-1", "Continue her usual combined pill"], "Her pill will no longer be reliable", ["Carbamazepine must be taken with milk", "Carbamazepine raises pill hormone levels", "Carbamazepine is not used in bipolar disorder"], "Carbamazepine speeds up the breakdown of the pill's hormones. Contraception can fail, and carbamazepine itself carries a pregnancy risk. A copper coil or a hormone coil, or injections, are advised.", "There is no milk rule. It lowers, not raises, hormone levels. Carbamazepine is used in bipolar disorder.", ["carbamazepine"], "stabilisers", 3, "contraception", "Recall carbamazepine makes the pill unreliable."),
  R("rv-ltg-pill", "Ms Thakur, 27, Shimla", "Bipolar disorder, stable on lamotrigine 200 mg. Starting the combined pill.", ["Tab Lametec 100 mg  1-0-1 (continue)", "Start combined oral contraceptive", "No change in plan"], "The pill will lower her lamotrigine", ["Lamotrigine makes all contraceptives fail", "The pill raises lamotrigine to toxic levels", "Lamotrigine must be stopped before the pill"], "Oestrogen speeds up lamotrigine's clearance, roughly halving the level, with a rise during pill-free days. Mood should be watched and the dose may need adjusting.", "Lamotrigine does not make contraceptives fail in the way carbamazepine does. The pill lowers, not raises, lamotrigine. Stopping lamotrigine is not needed.", ["lamotrigine"], "stabilisers", 5, "contraception and lamotrigine", "Recall that the pill lowers lamotrigine."),
  R("rv-ven-bp", "Mrs Banerjee, 49, Kolkata", "Depression partly better. Blood pressure 158/100 today.", ["Cap Veniz XR 150 mg  1-0-0, increase to 225 mg", "Blood pressure: no plan"], "Her blood pressure needs a plan first", ["Venlafaxine cannot be increased above 75 mg", "Venlafaxine lowers blood pressure", "Venlafaxine must be taken at night"], "Venlafaxine blocks the noradrenaline pump more at higher doses, raising blood pressure. With pressure already raised, increasing it without checking and treating the blood pressure is risky.", "Venlafaxine can go up to 375 mg in specialist care. It raises, not lowers, blood pressure. Morning dosing is usual.", ["venlafaxine"], "antidepressants", 3, "blood pressure on SNRIs", "Check blood pressure when raising venlafaxine."),
  R("rv-bupr-seiz", "Ms Arora, 22, Delhi", "Bulimia with daily vomiting. Wants to quit smoking.", ["Tab Smoquit SR 150 mg  1-0-1"], "Bupropion raises fit risk in bulimia", ["Bupropion is not used for quitting smoking", "Smoquit is not bupropion", "150 mg is the maximum single daily dose for all uses"], "Bupropion lowers the seizure threshold. In bulimia and anorexia, salt imbalance and low weight raise fit risk further, so bupropion is avoided. Nicotine replacement or varenicline are alternatives.", "Bupropion does help people stop smoking. Smoquit is a bupropion brand. 150 mg twice daily is a usual smoking-cessation dose.", ["bupropion"], "antidepressants", 4, "seizure risk", "Recall bupropion is avoided in eating disorders."),
  R("rv-trz-old", "Mr Saxena, 81, Lucknow", "Prostate trouble on tamsulosin. Poor sleep.", ["Tab Trazonil 100 mg  0-0-1", "Tab Urimax (tamsulosin 0.4 mg)  0-0-1 (continue)"], "Two alpha-1 blockers at night: falls", ["Trazodone is a stimulant", "Tamsulosin raises trazodone levels", "Trazodone must be taken in the morning"], "Trazodone and tamsulosin both block alpha-1 receptors. At night, on standing to pass urine, blood pressure drops and he may fall. A lower dose, or a different approach, is safer.", "Trazodone is sedating, not a stimulant. Tamsulosin does not raise trazodone. Night dosing suits its sedation.", ["trazodone"], "antidepressants", 3, "falls risk", "Add up alpha-1 block in older men."),
  R("rv-hal-dom", "Mr Kapoor, 74, Delhi", "Delirium after a fall; vomiting for two days. Potassium 3.2.", ["Inj Serenace 5 mg IM SOS", "Tab Domstal (domperidone 10 mg)  1-1-1 (continue)", "ECG: not done"], "QT risk: ECG and potassium first", ["Haloperidol can never be used in delirium", "Domperidone lowers potassium", "5 mg is the lowest dose of haloperidol"], "Both haloperidol and domperidone lengthen QT, and low potassium adds to the risk. An ECG, correcting potassium and the lowest dose (often 0.5 mg in older people) are needed, after non-drug delirium care.", "Haloperidol can be used briefly in delirium when needed. Vomiting, not domperidone, lowered his potassium. Much lower doses exist and suit older people.", ["haloperidol"], "antipsychotics", 4, "QT stacking", "Check QT before haloperidol beside domperidone."),
  R("rv-esc-hydrox", "Ms Joshi, 32, Pune", "Escitalopram 20 mg for anxiety. Itchy hives.", ["Tab Nexito 20 mg  1-0-0 (continue)", "Tab Atarax (hydroxyzine 25 mg)  1-0-1"], "Both lengthen the QT interval", ["Hydroxyzine is a steroid", "Hydroxyzine lowers escitalopram levels", "Escitalopram causes hives"], "Hydroxyzine, an older antihistamine, lengthens QT, as does escitalopram at higher doses. A non-sedating antihistamine with less QT effect is a safer choice.", "Hydroxyzine is an antihistamine, not a steroid. It does not change escitalopram levels. Hives have many causes; the problem here is the QT stacking.", ["escitalopram"], "antidepressants", 4, "QT stacking", "Recall hydroxyzine as a QT medicine."),
  R("rv-ser-ibu", "Mr Gupta, 66, Meerut", "Depression on sertraline. Osteoarthritis, had a stomach ulcer years ago.", ["Tab Zosert 100 mg  1-0-0 (continue)", "Tab Brufen 400 mg  1-1-1 long-term"], "High stomach bleeding risk", ["Sertraline makes ibuprofen stop working", "Zosert is not sertraline", "Ibuprofen raises sertraline to toxic levels"], "SSRIs weaken platelets and ibuprofen irritates the stomach and blocks platelets too. With a past ulcer, the bleeding risk is high. Paracetamol, or stomach protection if an anti-inflammatory is essential, is safer.", "Ibuprofen still works. Zosert is a sertraline brand. Ibuprofen does not raise sertraline levels.", ["sertraline"], "antidepressants", 3, "bleeding risk", "Spot SSRI plus anti-inflammatory bleeding risk."),
  R("rv-esc-warf", "Mr D'Souza, 72, Mangaluru", "Atrial fibrillation on warfarin. Depressed.", ["Tab Warf 5 mg  0-0-1 (continue)", "Tab Rexipra 10 mg  1-0-0 from today", "INR: next check in three months"], "INR and bleeding need closer checks", ["Escitalopram stops warfarin working", "Warfarin raises escitalopram to toxic levels", "Rexipra is a sleeping tablet"], "SSRIs reduce platelet function, adding to warfarin's effect, and some can shift the INR. Earlier INR checks and advice about bleeding signs are needed.", "Escitalopram does not stop warfarin working. Warfarin does not raise escitalopram. Rexipra is an escitalopram brand.", ["escitalopram"], "antidepressants", 3, "bleeding monitoring", "Monitor INR and bleeding after adding an SSRI to warfarin."),
  R("rv-clz-cbz", "Mr Yadav, 34, Patna", "On clozapine; had a fit last month.", ["Tab Skizoril 100 mg  1-0-2 (continue)", "Tab Tegretol 200 mg  1-0-1 for fits"], "Risk to white cells, and less clozapine", ["Carbamazepine raises clozapine levels", "Clozapine never causes fits", "Clozapine must be stopped after any fit"], "Both can suppress the bone marrow, and carbamazepine speeds up clozapine's clearance. Valproate or lamotrigine are usual choices for clozapine-related fits, alongside checking the clozapine level.", "Carbamazepine lowers, not raises, clozapine. Clozapine can cause dose-related fits. A fit does not always mean stopping; the dose, level and an anticonvulsant are reviewed.", ["clozapine", "carbamazepine"], "antipsychotics", 4, "blood count risk", "Avoid carbamazepine with clozapine."),
  R("rv-thx-clz", "Mr Prakash, 33, Coimbatore", "On clozapine, no stiffness, constipated for four days.", ["Tab Sizopin 100 mg  1-0-3 (continue)", "Tab Trihexy 2 mg  1-0-1 (added 'to prevent side effects')"], "It worsens clozapine constipation", ["Clozapine always causes severe stiffness", "Trihexyphenidyl is a laxative", "Trihexyphenidyl lowers clozapine levels"], "Clozapine rarely causes stiffness and is already strongly anticholinergic. Trihexyphenidyl adds to gut slowing, risking a blocked bowel. Stop it and treat the constipation.", "Clozapine rarely causes stiffness. Trihexyphenidyl constipates rather than relieving it. It does not change clozapine levels.", ["clozapine", "trihexyphenidyl"], "antipsychotics", 3, "anticholinergic burden", "Avoid routine anticholinergics with clozapine."),
  R("rv-pro-asthma", "Ms Mukherjee, 19, Kolkata", "Exam anxiety. Asthma since childhood, uses a salbutamol inhaler.", ["Tab Ciplar 10 mg  SOS before exams"], "Propranolol can set off asthma", ["Ciplar is not propranolol", "10 mg is far too high", "Propranolol must be taken every night"], "Propranolol blocks beta-2 receptors in the airways, which can cause severe bronchospasm and stop salbutamol working. It is avoided in asthma.", "Ciplar is a propranolol brand. 10 mg is a low dose. As-needed use is normal for performance anxiety.", ["propranolol"], "anxiety", 2, "asthma", "Recall propranolol is avoided in asthma."),
  R("rv-pro-insulin", "Mr Fernandes, 45, Panaji", "Type 1 diabetes on insulin. Shaky with anxiety.", ["Tab Inderal 20 mg  1-0-1 regular"], "It can hide low blood sugar warnings", ["Inderal is an antidepressant", "Propranolol raises blood sugar dangerously", "20 mg is the maximum dose"], "Low sugar normally causes shaking and a pounding heart through adrenaline. Propranolol blocks these, so hypos can go unnoticed. Another approach is safer, or close sugar monitoring.", "Inderal is propranolol, a beta-blocker. Its main risk here is masking hypos, not raising sugar. Higher doses exist.", ["propranolol"], "anxiety", 3, "diabetes", "Recall propranolol hides hypo warnings."),
  R("rv-mir-ok", "Mr Pereira, 66, Goa", "Depression with poor sleep and weight loss. No other medicines.", ["Tab Mirnite 15 mg  0-0-1", "Review in 14 days; weight and mood"], "No clear problem here", ["Mirtazapine must be taken in the morning", "15 mg is above the maximum", "Mirtazapine cannot be used in older adults"], "Mirtazapine at night suits depression with insomnia and weight loss, the dose is a usual start, and early review is planned. Spotting a sound prescription is part of checking.", "Morning dosing would waste its sedation. The maximum is 45 mg. Mirtazapine is commonly used in older adults.", ["mirtazapine"], "antidepressants", 1, "a sound prescription", "Recognise a reasonable prescription."),
  R("rv-ser-preg-ok", "Mrs Qureshi, 28, Bhopal", "Moderate depression in pregnancy. Therapy alone has not helped. Discussed risks and benefits.", ["Tab Serta 50 mg  1-0-0", "Shared plan with obstetrician; review in 14 days"], "No clear problem: a balanced plan", ["All antidepressants are banned in pregnancy", "Sertraline 50 mg is too high to start", "Sertraline must be stopped before delivery"], "Untreated depression in pregnancy carries risks too. Sertraline is one of the best-studied SSRIs in pregnancy and breastfeeding, and a shared plan with the obstetric team is good practice.", "Antidepressants are not banned in pregnancy; risks and benefits are weighed. 50 mg is the usual start. Stopping before delivery is not routine and risks relapse.", ["sertraline"], "antidepressants", 3, "a sound prescription", "Recognise a balanced pregnancy prescription."),
  R("rv-ari-flu", "Mr Gill, 31, Ludhiana", "Schizophrenia, stable on aripiprazole 15 mg. Now depressed.", ["Tab Arip MT 15 mg  1-0-0 (continue)", "Cap Prodep 20 mg  1-0-0 from today"], "Fluoxetine will push aripiprazole up", ["Fluoxetine cannot treat depression in schizophrenia", "Aripiprazole lowers fluoxetine to nothing", "Arip MT is not aripiprazole"], "Fluoxetine blocks CYP2D6, an aripiprazole exit. Aripiprazole levels rise, with more restlessness. The usual advice is to halve aripiprazole beside a strong CYP2D6 blocker.", "Antidepressants can be used for depression in schizophrenia. Aripiprazole does not lower fluoxetine much. Arip MT is an aripiprazole brand.", ["aripiprazole", "fluoxetine"], "antipsychotics", 3, "CYP2D6 interaction", "Adjust aripiprazole beside fluoxetine."),
  R("rv-dul-flv", "Ms Dutta, 44, Guwahati", "OCD on fluvoxamine. Diabetic nerve pain.", ["Tab Fluvoxin 100 mg  0-0-1 (continue)", "Cap Duzela 30 mg  1-0-0"], "Fluvoxamine pushes duloxetine far up", ["Duloxetine does not treat nerve pain", "Fluvoxamine must be taken in the morning", "Duzela is not duloxetine"], "Fluvoxamine strongly blocks CYP1A2, one of duloxetine's main exits. Levels can rise many-fold, with serotonin overload risk too. Another pain treatment is chosen.", "Duloxetine is used for diabetic nerve pain. Fluvoxamine is often taken at night. Duzela is a duloxetine brand.", ["duloxetine", "fluvoxamine"], "antidepressants", 4, "CYP1A2 interaction", "Avoid duloxetine with fluvoxamine."),
  R("rv-ago-liver", "Mr Sinha, 52, Ranchi", "Depression. Drinks heavily; liver tests raised.", ["Tab Agoprex 25 mg  0-0-1", "Liver tests: not planned"], "No liver tests, with a damaged liver", ["Agomelatine is taken in the morning", "25 mg is above the maximum", "Agomelatine is a benzodiazepine"], "Agomelatine can injure the liver. It is avoided in liver impairment and needs liver tests before and during treatment.", "It is taken at bedtime. 25 mg is the usual start (maximum 50 mg). It is a melatonin agonist, not a benzodiazepine.", ["agomelatine"], "antidepressants", 3, "liver monitoring", "Recall liver checks for agomelatine."),
  R("rv-ago-flv", "Ms Chopra, 35, Amritsar", "OCD on fluvoxamine. Poor sleep and low mood.", ["Tab Uvox 100 mg  0-0-1 (continue)", "Tab Valdoxan 25 mg  0-0-1"], "This pair must never be combined", ["Agomelatine treats OCD on its own", "Fluvoxamine is a sleeping tablet", "Valdoxan is not agomelatine"], "Agomelatine is cleared almost entirely by CYP1A2. Fluvoxamine blocks CYP1A2 strongly, so agomelatine levels can rise many-fold, with liver risk. The combination is contraindicated.", "Agomelatine is not an OCD treatment. Fluvoxamine is an SSRI. Valdoxan is an agomelatine brand.", ["agomelatine", "fluvoxamine"], "antidepressants", 4, "contraindicated combination", "Recall the fluvoxamine and agomelatine ban."),
  R("rv-lith-new-nolevel", "Mr Thakkar, 34, Rajkot", "First manic episode. Lithium started.", ["Tab Lithosun SR 400 mg  0-0-1", "Kidney, thyroid, calcium tests: not done", "Lithium level: not planned"], "No baseline tests or level plan", ["Lithium is not used for mania", "400 mg is a dangerous starting dose", "Lithium is taken only when mood is high"], "Lithium has a narrow safe range. Baseline kidney and thyroid function (and calcium, weight, ECG if indicated) are needed, then a level about 12 hours after the dose, a few days after starting and after each change.", "Lithium is used for mania. 400 mg is a common starting dose. It is taken every day, not only when mood is high.", ["lithium"], "stabilisers", 2, "lithium baseline", "Recall lithium baseline tests and level checks."),
  R("rv-li-thiazide", "Mrs Nair, 63, Kozhikode", "On lithium, level 0.7. Ankle swelling.", ["Tab Intalith CR 450 mg  0-0-1 (continue)", "Tab Aquazide 25 mg  1-0-0 from today"], "The thiazide will push lithium up", ["Hydrochlorothiazide lowers lithium", "Intalith is not lithium", "A level of 0.7 means lithium has stopped working"], "Thiazides make the kidneys reabsorb more lithium, raising levels by a quarter or more. Another treatment, or a lower lithium dose with early levels, is needed.", "Thiazides raise, not lower, lithium. Intalith CR is a lithium brand. 0.7 is a usual level.", ["lithium"], "stabilisers", 3, "lithium interaction", "Recall thiazides raise lithium."),
  R("rv-oxc-old", "Mr Kamath, 77, Karwar", "Bipolar disorder. Takes indapamide for blood pressure.", ["Tab Oxetol 300 mg  1-0-1", "Sodium: not planned"], "Sodium checks are missing", ["Oxcarbazepine raises sodium", "Oxcarbazepine is a benzodiazepine", "Oxetol is not oxcarbazepine"], "Oxcarbazepine often lowers sodium, and indapamide adds to it. Older age raises the risk. Sodium should be checked before and early on.", "It lowers, not raises, sodium. It is an anticonvulsant. Oxetol is an oxcarbazepine brand.", ["oxcarbazepine"], "stabilisers", 3, "sodium monitoring", "Plan sodium checks for oxcarbazepine."),
  R("rv-chlord-liver", "Mr Bhat, 55, Srinagar", "Alcohol withdrawal; advanced liver cirrhosis with jaundice.", ["Cap Librium 25 mg  1-1-1-1, reducing over 7 days"], "Long-acting drug in severe liver disease", ["Benzodiazepines do not help alcohol withdrawal", "Chlordiazepoxide must be injected", "A reducing course is never used"], "Chlordiazepoxide is broken down by the liver into long-lasting active products. With cirrhosis these accumulate, risking oversedation and encephalopathy. Lorazepam, which does not depend on those liver steps, is often chosen.", "Benzodiazepines are the main treatment for alcohol withdrawal. Chlordiazepoxide is given by mouth. Reducing courses are standard.", ["chlordiazepoxide", "lorazepam"], "substance", 4, "liver disease", "Choose a benzodiazepine for withdrawal with liver disease."),
  R("rv-thiamine", "Mr Sen, 52, Kolkata", "Heavy drinker admitted with confusion and unsteadiness after stopping alcohol.", ["Cap Librium 20 mg  1-1-1-1 reducing", "IV dextrose drip", "Thiamine: not prescribed"], "Thiamine is missing before glucose", ["Chlordiazepoxide is not used in alcohol withdrawal", "A reducing course is too fast", "Dextrose drips are banned in all hospitals"], "Heavy drinkers are often short of thiamine. Glucose uses thiamine up and can tip them into Wernicke's encephalopathy. Thiamine, given by injection when Wernicke's is suspected, comes first.", "Chlordiazepoxide is standard for withdrawal. A reducing course is the right shape. Glucose is fine once thiamine is given.", ["chlordiazepoxide"], "substance", 3, "thiamine", "Recall thiamine before glucose in heavy drinkers."),
  R("rv-ris-old", "Mrs Chatterjee, 84, Siliguri", "Dementia with agitation. Behaviour support not yet tried.", ["Tab Sizodon 2 mg  1-0-1"], "Dose too high, and non-drug care skipped", ["Risperidone is never used in dementia", "Risperidone must be given by injection", "2 mg is below the lowest tablet strength"], "Antipsychotics raise stroke and death risk in dementia. Non-drug approaches come first; if risperidone is needed, it starts at a low dose (such as 0.25 mg twice daily) for a short, reviewed period.", "Risperidone can be used briefly for severe agitation in dementia. It is a tablet. 2 mg tablets exist.", ["risperidone"], "neurocognitive", 4, "antipsychotics in dementia", "Use the lowest dose and non-drug care first in dementia."),
  R("rv-hal-lewy", "Mr Murthy, 76, Mysuru", "Fluctuating confusion, visual hallucinations and mild parkinsonism.", ["Tab Serenace 1.5 mg  0-0-1"], "Risk of severe sensitivity reaction", ["Haloperidol is only an injection", "1.5 mg is above the maximum", "Haloperidol is an antidepressant"], "Fluctuations, visual hallucinations and parkinsonism suggest dementia with Lewy bodies. D2 blockers like haloperidol can cause severe, sometimes fatal, sensitivity reactions. Specialist advice is needed.", "Haloperidol comes as tablets too. 1.5 mg is a small dose. It is an antipsychotic.", ["haloperidol"], "neurocognitive", 5, "Lewy body dementia", "Recognise antipsychotic sensitivity in Lewy body dementia."),
  R("rv-par-old", "Mrs Lal, 82, Kanpur", "Depression with memory complaints and constipation.", ["Tab Xet 20 mg  1-0-0"], "Most anticholinergic SSRI for her", ["Paroxetine is not an antidepressant", "20 mg is above the maximum", "Paroxetine must be taken at night only"], "Paroxetine's anticholinergic action can worsen memory and constipation in older adults, and it has troublesome withdrawal. Sertraline or escitalopram at a lower dose are usual choices.", "Paroxetine is an SSRI. 20 mg is a usual dose. Morning dosing is common.", ["paroxetine"], "antidepressants", 3, "drug choice for age", "Avoid paroxetine in older adults with memory problems."),
  R("rv-ami-od", "Mr Jha, 30, Darbhanga", "Severe depression with recent suicidal thoughts. Lives alone.", ["Tab Tryptomer 75 mg  0-0-1", "Supply: 90 tablets"], "Too big a supply given suicide risk", ["Amitriptyline cannot treat depression", "75 mg is above the maximum", "Amitriptyline must be taken in the morning"], "Tricyclics are dangerous in overdose. With recent suicidal thinking, small supplies held by a trusted person, frequent review, or a safer antidepressant are needed.", "Amitriptyline does treat depression. 75 mg is within range. Night dosing suits its sedation.", ["amitriptyline"], "antidepressants", 3, "overdose risk", "Limit dangerous medicines when suicide risk is present."),
  R("rv-li-supply", "Ms Gupta, 23, Jaipur", "Bipolar depression; recent overdose of paracetamol last month.", ["Tab Licab 300 mg  1-0-2", "Supply: three months at once"], "Too big a supply given suicide risk now", ["Lithium cannot be used in bipolar depression", "300 mg tablets do not exist", "Lithium must be taken only once a month"], "Lithium protects against suicide over time but is toxic in overdose. While risk is high, small supplies, a trusted person holding the medicine and close follow-up are needed.", "Lithium is used in bipolar depression. 300 mg tablets exist. It is a daily medicine.", ["lithium"], "stabilisers", 3, "overdose risk", "Plan small lithium supplies when suicide risk is high."),
  R("rv-mph-tics", "Kabir, 10, Mumbai", "ADHD on methylphenidate. Blood pressure 118/76, weight dropping on the growth chart.", ["Tab Addwize 10 mg  1-1-0 (continue)", "Weight: not discussed"], "His falling weight needs action", ["Methylphenidate raises appetite", "His blood pressure is dangerously high", "Addwize is not methylphenidate"], "Stimulants curb appetite. Falling down the growth chart needs a plan: breakfast before the dose, a bigger evening meal, a dose review or a break in holidays.", "Methylphenidate lowers appetite. 118/76 is within range for his age. Addwize is a methylphenidate brand.", ["methylphenidate"], "child", 2, "growth monitoring", "Act on falling weight on a stimulant."),
  R("rv-mph-heart", "Ms Varma, 30, Visakhapatnam", "Adult ADHD. Her brother died suddenly at 25; she faints on exercise.", ["Cap Concerta 18 mg  1-0-0"], "Her heart needs checking first", ["Methylphenidate is never used in adults", "18 mg is far above the maximum", "Concerta must be crushed"], "Stimulants raise pulse and blood pressure. Fainting on exercise or a family history of sudden death may point to a heart condition, so an ECG and cardiology review come first.", "Methylphenidate is used in adult ADHD. 18 mg is a starting dose. Concerta is a slow-release tablet that must not be crushed.", ["methylphenidate"], "child", 4, "heart screening", "Screen for heart risk before stimulants."),
  R("rv-dis-cardio", "Mr Iyer, 60, Chennai", "Alcohol dependence. Had a heart attack last year.", ["Tab Esperal 250 mg  1-0-0"], "Disulfiram is risky in heart disease", ["Disulfiram is only for women", "250 mg is too low", "Disulfiram must be injected"], "If someone on disulfiram drinks, the reaction brings a racing heart and blood pressure changes that can be dangerous with heart disease. Naltrexone or acamprosate are safer choices.", "Disulfiram is not limited by sex. 250 mg is a usual dose. It is a tablet.", ["disulfiram", "naltrexone", "acamprosate"], "substance", 4, "heart disease", "Avoid disulfiram in heart disease."),
  R("rv-nal-liver", "Mr Kohli, 50, Delhi", "Alcohol dependence with liver failure and jaundice.", ["Tab Nodict 50 mg  1-0-0"], "Avoid in liver failure; acamprosate fits", ["Naltrexone causes a reaction with alcohol", "50 mg is above the usual dose", "Naltrexone is only for smoking"], "Naltrexone is processed by the liver and is avoided in acute hepatitis or liver failure. Acamprosate, cleared by the kidneys, suits liver disease better.", "Naltrexone causes no reaction with alcohol. 50 mg is usual. It is used for alcohol and opioids, not smoking.", ["naltrexone", "acamprosate"], "substance", 4, "liver disease", "Choose acamprosate over naltrexone in liver failure."),
  R("rv-mel-flv", "Ms Bhatia, 40, Chandigarh", "OCD on fluvoxamine 200 mg. Poor sleep.", ["Tab Fluvoxin 100 mg  1-0-1 (continue)", "Tab Meloset 3 mg  0-0-1"], "Fluvoxamine pushes melatonin far up", ["Melatonin cannot be used for sleep", "Melatonin lowers fluvoxamine levels", "Fluvoxamine is a stimulant"], "Melatonin is cleared by CYP1A2, which fluvoxamine strongly blocks. A small melatonin dose, or another approach to sleep, is better.", "Melatonin is used for sleep. It does not lower fluvoxamine. Fluvoxamine is an SSRI.", ["melatonin", "fluvoxamine"], "anxiety", 4, "CYP1A2 interaction", "Recall fluvoxamine raises melatonin."),
  R("rv-ser-tram-old", "Mr Banerjee, 71, Asansol", "Depression on sertraline 100 mg. Post-operative pain after hernia repair.", ["Tab Daxid 100 mg  1-0-0 (continue)", "Tab Tramazac 50 mg  1-1-1 for 7 days"], "Tramadol adds serotonin and fit risk", ["Sertraline must be stopped after surgery", "Tramadol is a non-opioid painkiller", "Daxid lowers tramadol levels to nothing"], "Tramadol raises serotonin and lowers the seizure threshold. With sertraline, serotonin syndrome is possible, especially in older people. Paracetamol, with a different opioid if needed, is safer.", "Sertraline does not need stopping after surgery. Tramadol is an opioid with extra serotonin action. Sertraline does not abolish tramadol.", ["sertraline"], "antidepressants", 2, "serotonin interaction", "Spot tramadol with an SSRI."),
  R("rv-lin-ven", "Mrs Patil, 58, Kolhapur", "Infected diabetic foot on venlafaxine 150 mg.", ["Cap Venlor XR 150 mg  1-0-0 (continue)", "Tab Linospan (linezolid 600 mg)  1-0-1 for 14 days"], "Linezolid adds serotonin risk", ["Linezolid lowers venlafaxine to nothing", "Venlafaxine causes foot infections", "Linezolid is an antifungal"], "Linezolid weakly blocks MAO, so serotonin is broken down less. With venlafaxine, serotonin can build up dangerously. The teams decide whether to pause the antidepressant or monitor closely.", "Linezolid does not lower venlafaxine. Venlafaxine does not cause infections. Linezolid is an antibiotic.", ["venlafaxine"], "antidepressants", 3, "serotonin interaction", "Recall linezolid as a serotonin risk."),
  R("rv-que-low", "Mr Joshi, 58, Dehradun", "Insomnia only. Overweight with prediabetes. No psychosis or mood disorder.", ["Tab Seroquin 25 mg  0-0-1, long-term"], "A poor, risky long-term sleeping pill", ["Quetiapine 25 mg is a dangerously high dose", "Quetiapine is a benzodiazepine", "Seroquin is not quetiapine"], "Low-dose quetiapine acts as an antihistamine but still brings weight and sugar risks. For chronic insomnia, CBT for insomnia and treating causes come first.", "25 mg is a very low dose. Quetiapine is an antipsychotic. Seroquin is a quetiapine brand.", ["quetiapine"], "antipsychotics", 3, "off-label use", "Question long-term quetiapine for sleep."),
  R("rv-olz-smoke", "Mr Gill, 42, Jalandhar", "Stable on olanzapine 10 mg as an inpatient with no smoking. Going home; smokes 20 a day.", ["Tab Oliza 10 mg  0-0-1 (continue)", "Discharge: no review planned"], "Smoking again will lower olanzapine", ["Smoking raises olanzapine to toxic levels", "Olanzapine must be stopped when smoking", "Oliza is not olanzapine"], "Tobacco smoke speeds up CYP1A2, olanzapine's main exit. Once he smokes again, the same dose gives a lower level and relapse is possible. Early review and smoking advice are needed.", "Smoking lowers, not raises, olanzapine. Stopping olanzapine is not needed. Oliza is an olanzapine brand.", ["olanzapine"], "antipsychotics", 3, "smoking", "Plan for smoking changes on olanzapine."),
  R("rv-clz-quit", "Ms Fernandes, 38, Margao", "On clozapine 450 mg, smokes 30 a day. Admitted with pneumonia; cannot smoke on the ward.", ["Tab Lozapin 100 mg  1-0-3.5 (continue unchanged)", "Clozapine level: not planned"], "No smoking will push clozapine up", ["Clozapine must be stopped in pneumonia", "Smoking ban lowers clozapine levels", "450 mg is above the maximum"], "Without smoke, CYP1A2 slows and clozapine levels can rise sharply within days. Infection can raise levels too. A level check and dose reduction prevent toxicity. Nicotine patches do not speed the enzyme.", "Clozapine is not automatically stopped in infection, though levels and white cells are watched. Stopping smoking raises, not lowers, levels. The maximum is 900 mg.", ["clozapine"], "antipsychotics", 5, "clozapine and smoking", "Lower clozapine when a smoker stops."),
  R("rv-dvl-ok", "Ms Kaur, 34, Ludhiana", "Depression; tried sertraline without benefit. Blood pressure normal.", ["Tab Desvenlor 50 mg  1-0-0", "Blood pressure at review"], "No clear problem here", ["Desvenlafaxine is a benzodiazepine", "50 mg is above the maximum", "Desvenlafaxine must be crushed"], "Desvenlafaxine 50 mg is a usual dose, and checking blood pressure at review fits an SNRI. A sound prescription has no hidden flaw.", "It is an SNRI. 50 mg is a usual dose. It is a slow-release tablet that must be swallowed whole.", ["desvenlafaxine"], "antidepressants", 1, "a sound prescription", "Recognise a reasonable prescription."),
  R("rv-ltg-fast", "Mr Kapoor, 40, Delhi", "Bipolar depression. No other medicines.", ["Tab Lamictal 100 mg  1-0-0 from day one"], "Lamotrigine must start low and slow", ["Lamotrigine is only for mania", "100 mg tablets do not exist", "Lamotrigine must be taken with milk"], "Starting lamotrigine at a full dose raises the risk of serious rash, including Stevens-Johnson syndrome. It starts at 25 mg and is raised in slow steps.", "Lamotrigine is used to prevent bipolar depression, not mania. 100 mg tablets exist. There is no milk rule.", ["lamotrigine"], "stabilisers", 2, "lamotrigine titration", "Recall slow lamotrigine titration."),
  R("rv-ltg-restart", "Ms Pandey, 32, Prayagraj", "Stopped lamotrigine 200 mg ten days ago when she ran out. Wants to restart.", ["Tab Lamitor 200 mg  1-0-0, restart today at the same dose"], "After the gap it must be built up again", ["Lamotrigine can never be restarted", "200 mg is above the maximum", "Lamotrigine must be injected after a gap"], "The rash risk is linked to a fast rise. After more than about five half-lives off (a few days), lamotrigine is restarted at the starting dose and built up again.", "It can be restarted, slowly. 200 mg is within range. It is a tablet.", ["lamotrigine"], "stabilisers", 4, "restarting lamotrigine", "Rebuild lamotrigine after missed days."),
  R("rv-ser-bipolar", "Mr Desai, 28, Vadodara", "Depressed now. Two years ago he spent lakhs, slept 2 hours a night for days on end and felt chosen by God.", ["Tab Serta 50 mg  1-0-0 alone"], "Past mania: an antidepressant alone is risky", ["Sertraline 50 mg is too high", "Sertraline must be taken at night", "Sertraline cannot be used in men"], "This history describes mania, so this is bipolar depression. Antidepressants alone can trigger mania or rapid cycling. A mood stabiliser or an antipsychotic with evidence in bipolar depression comes first.", "50 mg is a usual dose. Timing is flexible. Sertraline is used in men and women.", ["sertraline", "lithium", "quetiapine"], "stabilisers", 4, "bipolar history", "Check for past mania before an antidepressant."),
  R("rv-flx-child-ok", "Diya, 16, Ahmedabad", "Moderate depression; therapy started. Family know warning signs.", ["Cap Flunil 10 mg  1-0-0, increase to 20 mg after review", "Review in 7 days, and family to call if worse"], "No clear problem: a careful plan", ["Fluoxetine is never used in teenagers", "10 mg tablets do not exist", "The review is far too early"], "Fluoxetine is the best-supported antidepressant in young people, started low, with early review and the family alert to warning signs.", "Fluoxetine is used in teenagers with depression. 10 mg is a real strength. Early review is good practice.", ["fluoxetine"], "antidepressants", 2, "a sound prescription", "Recognise a careful prescription for a young person."),
  R("rv-dia-elder", "Mrs Kulkarni, 83, Pune", "Anxiety and poor sleep. Lives alone.", ["Tab Valium 10 mg  0-0-1"], "High, long-acting dose for an 83-year-old", ["Diazepam is an antidepressant", "Diazepam must be taken in the morning", "10 mg tablets do not exist"], "Diazepam and its active products last for days in older people. A high dose builds up, causing falls, confusion and breathing problems. Non-drug help, or at most a short-acting option at a low dose briefly, is safer.", "Diazepam is a benzodiazepine. Timing does not remove the build-up. 10 mg tablets exist.", ["diazepam"], "anxiety", 2, "dose for age", "Avoid long-acting benzodiazepines in older adults."),
  R("rv-lor-alc", "Mr Pinto, 40, Mangaluru", "Drinks a bottle of feni most nights. Anxious.", ["Tab Ativan 2 mg  1-1-1 long-term"], "Long-term sedative with heavy drinking", ["Lorazepam is not a benzodiazepine", "2 mg tablets do not exist", "Lorazepam treats alcohol cravings long term"], "Benzodiazepines and alcohol add together on breathing. Long-term use with active drinking is dangerous. Alcohol treatment, with a supervised detox if he agrees, is the priority.", "Lorazepam is a benzodiazepine. 2 mg tablets exist. It does not treat cravings long term.", ["lorazepam"], "substance", 3, "sedative and alcohol", "Avoid long-term benzodiazepines in active drinking."),
  R("rv-bpn-benzo", "Mr Laldinpuia, 29, Aizawl", "On buprenorphine 12 mg. Says he cannot sleep.", ["Tab Addnok 2 mg + 8 mg  sublingual, 12 mg daily (continue)", "Tab Alprax 1 mg  0-0-2"], "Opioid plus benzodiazepine: breathing risk", ["Buprenorphine must be swallowed", "12 mg is above the maximum", "Alprazolam lowers buprenorphine levels"], "Benzodiazepines and opioids together are a leading cause of overdose deaths. Sleep problems are addressed in other ways, and if a benzodiazepine is ever used, it is short, supervised and discussed.", "Buprenorphine is taken under the tongue. Doses up to 24 mg or more are used. Alprazolam does not lower buprenorphine; it adds sedation.", ["buprenorphine", "alprazolam"], "substance", 3, "opioid with benzodiazepine", "Spot the opioid and benzodiazepine combination."),
  R("rv-pgb-opioid", "Mr Sandhu, 35, Bathinda", "Uses heroin. Asks for 'the capsules for nerve pain'.", ["Cap Pregeb 300 mg  1-0-1"], "Misuse and overdose risk with heroin", ["Pregabalin is an opioid", "300 mg capsules are too low to matter", "Pregabalin must be injected"], "Pregabalin is misused, especially with opioids, and adds to breathing depression. Prescribing it here needs a clear reason, low doses and controls, or a different approach.", "Pregabalin is not an opioid. 600 mg a day is a high dose. It is a capsule.", ["pregabalin"], "substance", 4, "misuse risk", "Recognise pregabalin misuse risk with opioids."),
  R("rv-cod-syrup", "Mr Ali, 22, Bhopal", "Cough for a month; on clonazepam for panic.", ["Syr containing codeine phosphate  10 mL three times daily for 15 days", "Tab Rivotril 0.5 mg  1-0-1 (continue)"], "An opioid syrup on top of clonazepam", ["Codeine is an antibiotic", "Clonazepam lowers codeine to nothing", "Cough syrups never contain codeine"], "Codeine is an opioid. With a benzodiazepine it adds sedation and slowed breathing, and codeine syrups are widely misused. The cause of a month-long cough also needs investigating.", "Codeine is an opioid. Clonazepam does not cancel it. Some cough syrups contain codeine.", ["clonazepam"], "substance", 3, "opioid with benzodiazepine", "Spot codeine in cough syrups."),
  R("rv-thx-glaucoma", "Mrs Shetty, 60, Mangaluru", "On haloperidol; has narrow-angle glaucoma.", ["Tab Serenace 5 mg  0-0-1 (continue)", "Tab Parkin 2 mg  1-0-1"], "It can trigger acute glaucoma", ["Parkin is not trihexyphenidyl", "Trihexyphenidyl worsens stiffness", "2 mg is above the maximum"], "Anticholinergics widen the pupil, which can block drainage of fluid from the eye in narrow-angle glaucoma and cause a painful emergency. Another approach to side effects is needed.", "Parkin is a trihexyphenidyl brand. It eases, not worsens, stiffness. 2 mg is a usual dose.", ["trihexyphenidyl"], "antipsychotics", 4, "glaucoma", "Recall anticholinergics are risky in narrow-angle glaucoma."),
  R("rv-dom-old", "Mrs Jain, 79, Udaipur", "Nausea from donepezil; heart failure, potassium low.", ["Tab Aricep 10 mg  0-0-1 (continue)", "Tab Domperidone 10 mg  1-1-1 long-term"], "Long-term domperidone: rhythm risk", ["Donepezil lowers domperidone levels", "Domperidone treats dementia", "Aricep is not donepezil"], "Domperidone lengthens QT, especially at higher doses, in older people and with heart disease or low potassium. It is used at the lowest dose for the shortest time, if at all. Reviewing the donepezil dose may solve the nausea.", "Donepezil does not lower domperidone. Domperidone is an anti-sickness medicine. Aricep is a donepezil brand.", ["donepezil"], "neurocognitive", 4, "QT risk", "Question long-term domperidone in older heart patients."),
  R("rv-ss-buspirone", "Mr Krishnan, 45, Chennai", "Generalised anxiety, already on escitalopram 10 mg.", ["Tab Nexito 10 mg  1-0-0 (continue)", "Tab Buspin 5 mg  1-1-1"], "No clear problem here", ["Buspirone is a benzodiazepine", "Buspirone must not be combined with any medicine", "5 mg is far above the maximum"], "Buspirone is sometimes added to an SSRI in anxiety. There is a small theoretical serotonin risk, so the person knows the warning signs, but the combination is used.", "Buspirone is not a benzodiazepine. It can be combined with care. 5 mg three times daily is a usual start.", ["buspirone", "escitalopram"], "anxiety", 4, "a sound prescription", "Recognise an acceptable combination."),
  R("rv-mir-sertr", "Ms Reddy, 31, Warangal", "Switching from sertraline (nausea) to mirtazapine.", ["Tab Serta 50 mg: stop", "Tab Mirtaz 15 mg  0-0-1 from today"], "No clear problem: a usual switch", ["Sertraline must be stopped a month before mirtazapine", "Mirtazapine and sertraline can never overlap at all", "15 mg mirtazapine is above the maximum"], "Switching from a low-dose SSRI to mirtazapine is usually done directly, watching for discontinuation symptoms. Long gaps are only needed for certain switches, such as to or from MAOIs or after fluoxetine.", "A month's gap is not needed here. Some overlap of SSRI and mirtazapine is even used deliberately. The maximum mirtazapine dose is 45 mg.", ["mirtazapine", "sertraline"], "antidepressants", 4, "switching", "Recognise a safe antidepressant switch."),
  R("rv-flx-switch", "Mrs Shah, 48, Ahmedabad", "Fluoxetine 40 mg stopped yesterday. Starting moclobemide, an MAO inhibitor.", ["Cap Fludac 40 mg: stopped yesterday", "Tab moclobemide 150 mg  1-0-1 from today"], "Far too soon after fluoxetine", ["Fluoxetine leaves the body within hours", "Moclobemide is a benzodiazepine", "40 mg fluoxetine is above the maximum"], "Fluoxetine and its active product have very long half-lives. A long washout is needed before an MAO inhibitor, or serotonin syndrome can occur.", "Fluoxetine stays for a long time. Moclobemide is a reversible MAO inhibitor antidepressant. 40 mg is within range.", ["fluoxetine"], "antidepressants", 5, "washout", "Recall the long fluoxetine washout before an MAO inhibitor."),
];
